import json,pathlib,collections,hashlib,sys,re
R=pathlib.Path(__file__).resolve().parent
def load(n):return json.loads((R/n).read_text())
def save(n,x):(R/n).write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
def params(r):return r['generation']['parameters']
def cases(rs):
 out=collections.Counter()
 from fractions import Fraction
 for r in rs:
  p=params(r);out['total']+=1;out[r['generation']['template']]+=1;out['h_positive' if p['h']>0 else 'h_negative']+=1;out['forcing_positive' if p['f']>0 else 'forcing_negative']+=1
  out['k_above_h' if p['k']>p['h'] else 'k_below_h' if p['k']<p['h'] else 'resonant_first']+=1
  a=p['v']-sum(Fraction(f,k-p['h']) for k,f in [(p['k'],p['f'])]+([(p['k2'],p['f2'])] if 'k2' in p else []) if k!=p['h'])
  out['A_zero' if a==0 else 'A_positive' if a>0 else 'A_negative']+=1
  if 'k2' in p:out['second_resonant' if p['k2']==p['h'] else 'second_nonresonant']+=1
 return dict(out)
